      "or",
      "but",
      "in",
      "on",
      "at",
      "to",
      "for",
      "of",
      "with",
      // French
      "le",
      "la",
      "les",
      "un",
      "une",
      "des",
      "de",
      "du",
      "et",
      "ou",
      "mais",
      "dans",
      "sur",
      "a",
      "au",
      "aux",
      "pour",
      "avec"
